blk=("/* ===== 1.1.32 늑구 '홈 왕관이 모으는 의미 없어 보임 → 활용도 재검토' → 👑 왕관 등급길 =====\n"
"   - 싱글 최고 점수(save.top.score)가 300 · 1천 · 2.5천 · 5천 · 1만 · 2.5만 · 6만 · 15만을 넘을 때마다 왕관 8단계(산호 → 심해)\n"
"   - 단계마다 진주 · 보석 한 번(홈 왕관을 눌러 받기), 판 진주 +2%/단계(싱글 · 탐험, 대전 제외), 홈 왕관은 단계 색 · Ⅰ~Ⅷ\n"
"   - 기준은 gf_scores 싱글 분포(중간 474 · 75% 1,570 · 90% 6,410 · 95% 18,221 · 99% 80,398) ===== */\n"
"try{(function(){var D="+js(D)+",NM="+js(NAMES)+",KS="+js(KS)+";for(var k in D.en)TRT[k]=D.en[k];for(k in D.ja)TRJ[k]=D.ja[k];if(SUBL&&D[SUBL])for(k in D[SUBL])TRX[k]=D[SUBL][k];\n"
"  var TH=[300,1000,2500,5000,10000,25000,60000,150000],RP=[500,1000,2000,3000,5000,8000,12000,20000],RG=[5,5,10,10,15,20,30,50],COL=['#FF8A80','#F5C9A0','#CFD8DC','#FFD54F','#FF5470','#4FA3FF','#B9F2FF','#8C6CFF'],RM=['Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ','Ⅵ','Ⅶ','Ⅷ'];\n"
"  function best(){try{return save.top&&save.top.score>0?+save.top.score:0}catch(e){return 0}}\n"
"  function tier(){var b=best(),n=0;for(var i=0;i<TH.length;i++)if(b>=TH[i])n=i+1;return n}\n"
"  function ready(){return Math.max(0,tier()-(save.crg|0))}\n"
"  window.GF_CROWN=tier;\n"
"  var rgC=runGain;runGain=function(){var g=rgC.apply(this,arguments);try{if(!fair()){var t=tier();if(t)g=Math.floor(g*(1+.02*t))}}catch(e){}return g};\n"
"  var st=document.createElement('style');st.textContent='#hmBest{cursor:pointer;position:relative}#hmBest .crm{position:absolute;left:-4px;bottom:-5px;min-width:15px;height:15px;padding:0 3px;border-radius:8px;font:700 10px/15px sans-serif;color:#2b1b00;text-align:center;box-shadow:0 1px 2px rgba(0,0,0,.35)}#hmBest .crd{position:absolute;right:-3px;top:-3px;width:10px;height:10px;border-radius:50%;background:#ff3b3b;box-shadow:0 0 0 2px #fff}'+\n"
"   '#crownP .cr-row{display:grid;grid-template-columns:30px 1fr auto;gap:8px;align-items:center;padding:7px 8px;border-radius:12px;background:rgba(0,0,0,.05);margin:5px 0;text-align:left}#crownP .cr-row.on{background:rgba(255,213,79,.25)}#crownP .cr-row.lock{opacity:.55}#crownP .cr-ic{width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;font:700 13px sans-serif;color:#2b1b00}#crownP .cr-row b{display:block;font-size:15px}#crownP .cr-row small{font-size:12px;opacity:.8}#crownP .cr-row button{min-width:64px;padding:6px 10px;border-radius:12px;border:0;background:#ff9f1a;color:#fff;font-weight:700}#crownP .cr-row button:disabled{background:#c9c2b8;color:#fff;opacity:.8}#crownP .cr-row em{font-style:normal;font-size:12px;opacity:.7}#crownP .cr-list{max-height:52vh;overflow:auto}#crownP .cr-sum{font-size:13px;margin:2px 0 6px}';document.head.appendChild(st);\n"
"  function paint(){try{var hb=$('hmBest');if(!hb)return;var t=tier(),m=hb.querySelector('.crm');if(t){if(!m){m=document.createElement('i');m.className='crm';hb.appendChild(m)}m.textContent=RM[t-1];m.style.background=COL[t-1]}else if(m)m.remove();\n"
"    var d=hb.querySelector('.crd'),r=ready()>0;if(r&&!d){d=document.createElement('i');d.className='crd';hb.appendChild(d)}else if(!r&&d)d.remove();if(!hb.dataset.cr){hb.dataset.cr=1;hb.addEventListener('click',function(e){e.stopPropagation();open()})}}catch(e){}}\n"
"  function take(i){if(i!==(save.crg|0)||i>=tier())return;save.crg=i+1;save.pearls=(save.pearls||0)+RP[i];save.gems=(save.gems||0)+RG[i];persist();try{buzzBuy()}catch(e){}try{refreshHome(true)}catch(e){}banner('👑 '+T(NM[i]),T('진주 ')+nf(RP[i])+' · '+T('보석 ')+RG[i]);try{crumb('crown'+(i+1))}catch(e){}}\n"
"  function open(){var el=$('crownP');if(!el){el=document.createElement('div');el.className='overlay';el.id='crownP';el.hidden=true;el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');document.body.appendChild(el);el.addEventListener('click',function(e){if(e.target===el)el.hidden=true})}\n"
"    var t=tier(),b=best(),nx=t<TH.length?TH[t]-b:0,h='<div class=\"panel aw-panel\"><h1>👑 '+T(KS[0])+'</h1><p class=\"lead\">'+T(KS[1])+'</p><p class=\"cr-sum\">'+T(KS[2])+' <b>'+nf(b)+T('점')+'</b>'+(nx>0?' · '+T(KS[3])+' <b>'+nf(nx)+T('점')+'</b>':'')+' · '+T(KS[4])+' <b>+'+(2*t)+'%</b></p><div class=\"cr-list\">';\n"
"    for(var i=0;i<TH.length;i++){var got=i<(save.crg|0),can=!got&&i<t,nxt=i===(save.crg|0);h+='<div class=\"cr-row'+(i<t?' on':' lock')+'\"><span class=\"cr-ic\" style=\"background:'+COL[i]+'\">'+RM[i]+'</span><div><b>'+T(NM[i])+'</b><small>'+nf(TH[i])+T('점')+' · 🫧'+nf(RP[i])+' · 💎'+RG[i]+' · +'+(2*(i+1))+'%</small></div>'+(got?'<em>'+T('받음')+'</em>':can?'<button type=\"button\" data-cr=\"'+i+'\"'+(nxt?'':' disabled')+'>'+T('받기')+'</button>':'<em>🔒</em>')+'</div>'}\n"
"    h+='</div><button class=\"btn\" type=\"button\" id=\"crX\">'+T('닫기')+'</button></div>';el.innerHTML=h;el.hidden=false;\n"
"    $('crX').onclick=function(){el.hidden=true};el.querySelectorAll('[data-cr]').forEach(function(x){x.onclick=function(){take(+x.dataset.cr);open();paint()}})}\n"
"  /* 새 왕관에 오르면 판이 끝난 뒤 알림 한 번 */\n"
"  function note(){var t=tier();if(save.crn==null){save.crn=t;persist();return}if(t>(save.crn|0)){save.crn=t;persist();setTimeout(function(){banner('👑 '+T(KS[5]),T(NM[t-1])+' · '+T(KS[4])+' +'+(2*t)+'%')},1800)}}\n"
"  var rhC=refreshHome;refreshHome=function(){var r=rhC.apply(this,arguments);try{note();paint()}catch(e){}return r};\n"
"  setTimeout(function(){try{note();paint()}catch(e){}},1500)})()}catch(e){}\n")
A="if(window.claude&&window.claude.hot&&window.claude.hot.ready)window.claude.hot.ready(boot);else boot();"
assert w.count(A)==1;w=w.replace(A,blk+A);p.append({'a':A,'b':blk+A})
